import astropy.modeling.separable as sep
import inspect

source_lines = inspect.getsource(sep).split('\n')

# Find _separable function definition
for i, line in enumerate(source_lines):
    if 'def _separable' in line:
        print(f"Found _separable at line {i}:")
        for j in range(i, min(len(source_lines), i+150)):
            print(f"{j}: {source_lines[j]}")
        break

import astropy.modeling.separable as sep
import inspect

source_lines = inspect.getsource(sep).split('\n')

# Find _cstack and _cdot
for i, line in enumerate(source_lines):
    if 'def _cstack' in line or 'def _cdot' in line:
        print(f"Found {line.strip()} at line {i}:")
        for j in range(i, min(len(source_lines), i+40)):
            print(f"{j}: {source_lines[j]}")
        print("\n" + "="*80 + "\n")
